patch:
diff --git a/source/standalone/local-socket-url.ts b/source/standalone/local-socket-url.ts
new file mode 100644
index 0000000..23c82f4
--- /dev/null
+++ b/source/standalone/local-socket-url.ts
@@ -0,0 +1,4 @@
+// eslint-disable-next-line @typescript-eslint/naming-convention
+export default function isLocalSocketURL(url: URL) {
+	return url.protocol === 'unix:' || url.hostname === 'unix' || url.hostname === 'local';
+}
diff --git a/test/local-socket-url.ts b/test/local-socket-url.ts
new file mode 100644
index 0000000..a86a25c
--- /dev/null
+++ b/test/local-socket-url.ts
@@ -0,0 +1,28 @@
+import test from 'ava';
+import isLocalSocketURL from '../source/standalone/local-socket-url.js';
+
+test('accepts the `unix:` protocol', t => {
+	t.true(isLocalSocketURL(new URL('unix:/var/run/docker.sock:/containers/json')));
+});
+
+test('accepts the `unix` hostname', t => {
+	t.true(isLocalSocketURL(new URL('http://unix:/var/run/docker.sock:/containers/json')));
+	t.true(isLocalSocketURL(new URL('https://unix/foo')));
+});
+
+test('accepts the `local` hostname', t => {
+	t.true(isLocalSocketURL(new URL('http://local:/var/run/docker.sock:/containers/json')));
+	t.true(isLocalSocketURL(new URL('https://local/foo')));
+});
+
+test('rejects other URLs', t => {
+	t.false(isLocalSocketURL(new URL('http://example.com')));
+	t.false(isLocalSocketURL(new URL('http://localhost')));
+	t.false(isLocalSocketURL(new URL('http://unix.example.com')));
+	t.false(isLocalSocketURL(new URL('http://local.example.com')));
+	t.false(isLocalSocketURL(new URL('file:///unix')));
+});
+
+test('throws on non-URL input like the reference', t => {
+	t.throws(() => isLocalSocketURL(undefined as unknown as URL), {instanceOf: TypeError});
+});
